const { parseTaskId } = require('./bench/sandbox/parse-task-id-ht.js');

// Current format
console.assert(JSON.stringify(parseTaskId('b3d1b5f4-ac17-4a48-8f81-e0a5c5a8fe7d/42')) === JSON.stringify({ session: 'b3d1b5f4-ac17-4a48-8f81-e0a5c5a8fe7d', seq: 42, legacy: false }), 'current 42');
console.assert(JSON.stringify(parseTaskId('df63dcd1-69b2-48ae-926b-1f360ad2fc0c/7')) === JSON.stringify({ session: 'df63dcd1-69b2-48ae-926b-1f360ad2fc0c', seq: 7, legacy: false }), 'current 7');

// Legacy format
console.assert(JSON.stringify(parseTaskId('a3f9c812/5')) === JSON.stringify({ session: 'a3f9c812', seq: 5, legacy: true }), 'legacy');

// Invalid
console.assert(parseTaskId(null) === null, 'null');
console.assert(parseTaskId('') === null, 'empty');
console.assert(parseTaskId('noslash') === null, 'no slash');
console.assert(parseTaskId('b3d1b5f4-ac17-4a48-8f81-e0a5c5a8fe7d/0') === null, 'seq=0');
console.assert(parseTaskId('b3d1b5f4-ac17-4a48-8f81-e0a5c5a8fe7d/abc') === null, 'non-numeric seq');
console.assert(parseTaskId('notauuid/5') === null, 'bad prefix');

console.log('all assertions passed');
" 2>&1
